# Predeclared criteria and separate result evidence bundles.
validation_report<-function(results,acceptance_policy,manifests,context=NULL){
 rr<-.vs_index(results,'result_id','results');rows<-rr$rows;policy<-.ex_object(acceptance_policy,'acceptance_policy');manifests<-.ex_object(manifests,'manifests');for(key in c('policy_id','version','reference')).vb_string(policy[[key]],key);started<-.cr_data_date(manifests$evaluation_started_at,'evaluation_started_at');if(.cr_data_date(policy$declared_at,'policy declared_at')>started).cr_error('VALIDATION_POLICY_LOOKAHEAD','Acceptance policy must precede evaluation');mkeys<-c('model_manifest','data_manifest','split_manifest');for(key in mkeys).vs_hashes(manifests[[key]],key);required<-.ex_ids(policy$required_result_ids,'required_result_ids');criteria<-.vs_index(policy$criteria,'criterion_id','criteria')$rows;violations<-findings<-bundles<-list();issue<-function(code,unit,detail)violations[[length(violations)+1]]<<-list(code=code,unit_id=unit,detail=detail)
 for(i in seq_along(rows)){row<-rows[[i]];rid<-row$result_id;result<-row$result;if(inherits(result,'CalcResult'))result<-result$value;result<-.ex_object(result,'validation result');rows[[i]]$result<-result;if(!identical(result$artifact_type,'ValidationResult')).cr_error('VALIDATION_REPORT_RESULT','Only ValidationResult payloads can be bundled');for(key in c('reference','data_origin')).vb_string(row[[key]],key);if(!row$data_origin%in%c('SYNTHETIC','EMPIRICAL','SOFTWARE','MIXED')).cr_error('VALIDATION_REPORT_ORIGIN','Explicit separate data-origin tag required');bindings<-.vs_hashes(row$manifest_hashes,'result manifest_hashes');expected<-setNames(lapply(mkeys,function(key).cr_hash(manifests[[key]])),mkeys);if(!identical(.cr_hash(bindings),.cr_hash(expected)))issue('RESULT_MANIFEST_MISMATCH',rid,'Result does not match declared model/data/split manifests');bundles[[length(bundles)+1]]<-list(result_id=rid,result=result,reference=row$reference,data_origin=row$data_origin,result_hash=.cr_hash(result))};index<-setNames(rows,vapply(rows,function(r)r$result_id,character(1)))
 for(rid in required){if(is.null(index[[rid]]))issue('MISSING_REQUIRED_RESULT',rid,'Required result is absent')else{r<-index[[rid]]$result;if(identical(r$applicability,'NOT_APPLICABLE')||isTRUE(r$decision$status%in%c('FAIL','BLOCKED','NOT_APPLICABLE')))issue('NONPASS_REQUIRED_RESULT',rid,'Required result is failed, blocked or non-applicable')};if(!any(vapply(criteria,function(c)identical(c$result_id,rid),logical(1))))issue('UNEVALUATED_REQUIRED_RESULT',rid,'Required result has no predeclared acceptance criterion')}
 scalar_number<-function(v)is.numeric(v)&&length(v)==1&&is.finite(v)
 for(c in criteria){cid<-c$criterion_id;rid<-.vb_string(c$result_id,'criterion result_id');path<-unlist(c$path,use.names=FALSE);if(!is.character(path)||!length(path)||anyNA(path)||any(!nzchar(path))).cr_error('VALIDATION_REPORT_PATH','Criterion path is nonempty ordered array of object keys');op<-c$operator;if(!op%in%c('LE','GE','EQ','BETWEEN')).cr_error('VALIDATION_REPORT_OPERATOR','Use LE, GE, EQ or BETWEEN');.vb_string(c$rationale,'criterion rationale');threshold<-c$threshold;if(op=='BETWEEN'){bounds<-.vb_vec(threshold,'criterion bounds');if(length(bounds)!=2||bounds[1]>bounds[2]).cr_error('VALIDATION_REPORT_THRESHOLD','Two ordered numeric bounds required');lo<-bounds[1];hi<-bounds[2]}else if(op!='EQ'){.vb_number(threshold,'criterion threshold')}else if(length(threshold)!=1||!((is.character(threshold)||is.logical(threshold))&&!is.na(threshold)||scalar_number(threshold))).cr_error('VALIDATION_REPORT_THRESHOLD','EQ requires finite JSON scalar');value<-index[[rid]]$result;for(key in path)value<-if(.cr_object(value))value[[key]]else NULL;status<-'NOT_ESTIMABLE';if(!is.null(value)){if(op=='EQ'){comparable<-(is.logical(value)&&length(value)==1&&!is.na(value)&&is.logical(threshold))||(is.character(value)&&length(value)==1&&!is.na(value)&&is.character(threshold))||(scalar_number(value)&&scalar_number(threshold));if(comparable)status<-if(value==threshold)'PASS'else'FAIL'}else if(scalar_number(value)){passed<-if(op=='BETWEEN')lo<=value&&value<=hi else if(op=='LE')value<=threshold else value>=threshold;status<-if(passed)'PASS'else'FAIL'}};if(status!='PASS')issue(paste0('CRITERION_',status),cid,paste(c(rid,path),collapse='/'));findings[[length(findings)+1]]<-list(criterion_id=cid,result_id=rid,path=as.list(path),observed=value,operator=op,threshold=threshold,status=status,rationale=c$rationale)}
 payload<-list(acceptance_policy=policy,manifests=manifests,applicability='APPLICABLE',findings=findings,results=bundles,metrics=list(required_results=length(required),criteria=length(criteria),passed_criteria=sum(vapply(findings,function(c)c$status=='PASS',logical(1)))),p_values_combined=FALSE,acceptance_scope='PREDECLARED_VALIDATION_CRITERIA_ONLY',renderable_report=list(title='Validation acceptance report',result_order=lapply(bundles,function(r)r$result_id),open_issues=lapply(violations,function(v)paste(v$code,v$unit_id,sep=':'))));.vs_finish('validation_report',payload,violations,list(results=rows,acceptance_policy=policy,manifests=manifests),context)
}
